func test_hero_enters_doorway_up_to_door_leaf() -> void:
	var s := _sim(LEVEL)
	var cols := {}
	for c in s.state.level["colliders"]:
		cols[c["id"]] = c
	var door: Dictionary = cols["keeper_house_door"]
	var wall: Dictionary = cols["keeper_house_w"]
	var r := float(s.bal["player"]["radius"])
	var wall_front := float(wall["y"]) + float(wall["hy"])
	var leaf_front := float(door["y"]) + float(door["hy"])
	s.state.player["pos"] = Vector2(float(door["x"]), wall_front + 4.0)
	_ticks(s, 120, Vector2.UP)
	var p: Vector2 = s.state.player["pos"]
	assert_almost_eq(p.y, leaf_front + r, 0.01, "упёрся в полотно двери")
	assert_lt(p.y, wall_front + r - 0.05, "глубже плоскости стен (в проёме)")
	assert_almost_eq(p.x, float(door["x"]), 0.01, "остался на оси двери")
	s.state.player["pos"] = Vector2(float(door["x"]) + float(door["hx"]) + r + 0.2, wall_front + 2.0)
	_ticks(s, 120, Vector2.UP)
	assert_almost_eq(s.state.player["pos"].y, wall_front + r, 0.01, "мимо двери — в стену")


